sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;
    c.searchText = '';
    c.filteredEmployees = [];

    // Function to filter employees based on search text
    c.filterResults = function() {
        if (!c.data || !c.data.employees) return;

        var searchLower = c.searchText.toLowerCase();
        c.filteredEmployees = c.data.employees.filter(function(emp) {
            return emp.name.toLowerCase().includes(searchLower) ||
                   emp.department.toLowerCase().includes(searchLower) ||
                   emp.manager.toLowerCase().includes(searchLower);
        });
    };

    // Watch for search text changes and update filtered results
    $scope.$watch(function() {
        return c.searchText;
    }, function() {
        $timeout(c.filterResults, 300); // Adding slight delay for performance
    });

    // Initialize the filtering
    c.filterResults();
};

sp_widget.css:
.filter-search-container {
    padding: 20px;
    background: white;
    border-radius: 8px;
    box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
}
.search-input, .filter-dropdown {
    padding: 10px;
    margin: 10px 0;
    width: 100%;
    border: 1px solid #ccc;
    border-radius: 5px;
}
.table {
    width: 100%;
    border-collapse: collapse;
}
th, td {
    padding: 10px;
    border-bottom: 1px solid #ddd;
}
th {
    background: #f4f4f4;
    text-align: left;
}

sp_widget.script:
(function() {
    var result = [];

    var gr = new GlideRecord('sys_user'); // Replace 'your_table' with the actual table name
    if (gr.isValid()) {  // Check if the table exists
        gr.addQuery('active', true);  // Example condition (modify as needed)
        gr.orderByDesc('sys_created_on');  // Order by latest records
        gr.setLimit(20);  // Display only first 20 records
        gr.query();

        while (gr.next()) {
            result.push({
                sys_id: gr.getUniqueValue(),
                name: gr.getValue('employee_name'),  // Replace with actual field
                department: gr.getValue('department'),  // Replace with actual field
                manager: gr.getValue('manager'),  // Replace with actual field
                start_date: gr.getValue('start_date')  // Replace with actual field
            });
        }
    }

    data.employees = result;
})();
